from pysat.solvers import Glucose3

# Sudoku with block size 3 (9x9 grid)
# Variables: x[i][j][v] = True means cell (i,j) has value v+1
# Index in row-major order: cell (i,j) is at index i*9+j

# Fixed values
fixed = {
    2: 3,   # row 0, col 2
    11: 6,  # row 1, col 2
    13: 8,  # row 1, col 4
    20: 9,  # row 2, col 2
    22: 2,  # row 2, col 4
    35: 7,  # row 3, col 8
    42: 2,  # row 4, col 6
    46: 9,  # row 5, col 1
    50: 4,  # row 5, col 5
    57: 6,  # row 6, col 3
    58: 4,  # row 6, col 4
    60: 9,  # row 6, col 6
    62: 8,  # row 6, col 8
    69: 5,  # row 7, col 6
    78: 6,  # row 8, col 6
    79: 4,  # row 8, col 7
}

# Create variable mapping: var(i, j, v) where i,j in 0..8, v in 0..8 (value v+1)
def var(i, j, v):
    return i * 81 + j * 9 + v + 1  # 1-indexed for SAT solver

solver = Glucose3()

# Each cell has exactly one value
for i in range(9):
    for j in range(9):
        # At least one value
        solver.add_clause([var(i, j, v) for v in range(9)])
        # At most one value
        for v1 in range(9):
            for v2 in range(v1+1, 9):
                solver.add_clause([-var(i, j, v1), -var(i, j, v2)])

# Each row has each value exactly once
for i in range(9):
    for v in range(9):
        # At least one cell in row i has value v
        solver.add_clause([var(i, j, v) for j in range(9)])
        # At most one cell in row i has value v
        for j1 in range(9):
            for j2 in range(j1+1, 9):
                solver.add_clause([-var(i, j1, v), -var(i, j2, v)])

# Each column has each value exactly once
for j in range(9):
    for v in range(9):
        # At least one cell in column j has value v
        solver.add_clause([var(i, j, v) for i in range(9)])
        # At most one cell in column j has value v
        for i1 in range(9):
            for i2 in range(i1+1, 9):
                solver.add_clause([-var(i1, j, v), -var(i2, j, v)])

# Each 3x3 block has each value exactly once
for bi in range(3):
    for bj in range(3):
        for v in range(9):
            cells = []
            for di in range(3):
                for dj in range(3):
                    cells.append(var(bi*3+di, bj*3+dj, v))
            # At least one
            solver.add_clause(cells)
            # At most one
            for c1 in range(len(cells)):
                for c2 in range(c1+1, len(cells)):
                    solver.add_clause([-cells[c1], -cells[c2]])

# Fixed values
for idx, val in fixed.items():
    i = idx // 9
    j = idx % 9
    v = val - 1
    solver.add_clause([var(i, j, v)])

# Solve
if solver.solve():
    model = solver.get_model()
    # Extract solution
    grid = [0] * 81
    for i in range(9):
        for j in range(9):
            for v in range(9):
                if var(i, j, v) in model:
                    grid[i*9+j] = v + 1
    print("Solution found:")
    for i in range(9):
        print(grid[i*9:(i+1)*9])
    print("Flat:", grid)
else:
    print("UNSATISFIABLE")

solver.delete()
